// BookCard.jsx
import { Link } from "react-router-dom";
import styled from "styled-components";
import Mosaic from "./Mosaic";
import withImageLoading from "../components/hoc/withImageLoading";

// Styled Components
const CardWrapper = styled.div`
  width: 100%;
  aspect-ratio: 2 / 3;
  position: relative;
`;

const CardLink = styled(Link)`
  text-decoration: none;
  width: 100%;
  height: 100%;
  display: block;
`;

const Card = styled.div`
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;

  transform: scale(1);
  transition:
    transform 0.35s ease,
    box-shadow 0.35s ease;

  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.25);

  &:hover {
    transform: scale(1.08);
    z-index: 10;
    box-shadow: 0 25px 50px rgba(0, 0, 0, 0.45);
  }

  &:hover .overlay {
    opacity: 1;
    transform: translateY(0);
  }

  &:hover img {
    transform: scale(1.05);
  }
`;

const BookImage = styled.img`
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.35s ease;
`;

const Overlay = styled.div`
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  padding: 16px;

  background: linear-gradient(
    to top,
    rgba(0, 0, 0, 0.85),
    rgba(0, 0, 0, 0.4),
    transparent
  );

  opacity: 0;
  transform: translateY(10px);
  transition:
    opacity 0.3s ease,
    transform 0.3s ease;
`;

const Title = styled.h5`
  margin: 0;
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
`;

const Author = styled.p`
  margin: 4px 0 0;
  color: #ccc;
  font-size: 0.85rem;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
`;

// Image-level loading HOC usage
const BookImageWithLoading = withImageLoading(BookImage);

const BookCard = ({ isbn, thumbnail, title, author }) => {
  return (
    <CardWrapper>
      <CardLink to={`/book/${isbn}`}>
        <Card>
          <Mosaic thumbnail={thumbnail} blur={14} tileSize={140} opacity={0.35}>
            <BookImageWithLoading src={thumbnail} alt={title} />
            <Overlay className="overlay">
              <Title title={title}>{title}</Title>
              <Author title={author}>{author}</Author>
            </Overlay>
          </Mosaic>
        </Card>
      </CardLink>
    </CardWrapper>
  );
};

export default BookCard;
